import { FunctionsHttpError } from '@supabase/supabase-js';
import { supabase } from './supabase';

export type BusinessSubscriptionView = 'success' | 'processing' | 'failed' | 'cancelled';

export type BusinessSubscriptionCheckoutResponse = {
  success: true;
  checkoutId: string;
  subscriptionId: string;
  stripeAccountId: string;
  clientSecret: string | null;
  status: string;
};

export type BusinessSubscriptionVerification = {
  success: true;
  checkoutId: string;
  status: string;
  paymentStatus: string | null;
  view: BusinessSubscriptionView;
};

export class BusinessSubscriptionCheckoutError extends Error {
  code?: string;
  details?: unknown;

  constructor(message: string, code?: string, details?: unknown) {
    super(message);
    this.name = 'BusinessSubscriptionCheckoutError';
    this.code = code;
    this.details = details;
  }
}

async function invokeBusinessSubscription<T>(
  action: 'create' | 'verify',
  input: Record<string, unknown>,
): Promise<T> {
  const { data, error } = await supabase.functions.invoke('business-subscription-checkout', {
    body: { action, input },
  });

  if (error) {
    if (error instanceof FunctionsHttpError) {
      try {
        const payload = await error.context.json();
        throw new BusinessSubscriptionCheckoutError(
          payload?.error || error.message,
          payload?.code,
          payload?.details,
        );
      } catch (contextError) {
        if (contextError instanceof BusinessSubscriptionCheckoutError) throw contextError;
      }
    }
    throw new BusinessSubscriptionCheckoutError(error.message || 'Subscription checkout is unavailable.');
  }

  if (!data?.success) {
    throw new BusinessSubscriptionCheckoutError(
      data?.error || 'Subscription checkout is unavailable.',
      data?.code,
      data?.details,
    );
  }

  return data as T;
}

export const createBusinessSubscriptionCheckout = (input: {
  planId: string;
  requestId: string;
  email: string;
  name: string;
}) => invokeBusinessSubscription<BusinessSubscriptionCheckoutResponse>('create', input);

export const verifyBusinessSubscriptionCheckout = (checkoutId: string) =>
  invokeBusinessSubscription<BusinessSubscriptionVerification>('verify', { checkoutId });
